namespace Charon.Generator;

public static class SourceGeneratorExtensions
{
    public static void AddSource(this SourceProductionContext context, ClassModel classModel, string code, string extension = ".g.cs")
    {
        var source = string.IsNullOrEmpty(classModel.Namespace)
            ? $$"""
// <auto-generated/>
#nullable enable

{{code}}
"""
            : $$"""
// <auto-generated/>
#nullable enable

namespace {{classModel.Namespace}};

{{code}}
""";

        var hintName = string.IsNullOrEmpty(classModel.Namespace)
             ? $"{classModel.Name}{extension}"
             : $"{classModel.Namespace}.{classModel.Name}{extension}";

        context.AddSource(hintName, source);
    }
}
